/**
 * An archived project freezes its issues and everything attached to them,
 * even when the issues themselves were not archived. Writes call this after
 * the permission check, so a caller without permission still gets that error.
 */
export async function assertProjectLive(
  orgId: OrgId,
  issue: Issue,
): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Issue", issue.id, project);
}

